// Writes supabase/047_graphic_design_q1.sql: "Графикалық дизайн" 7 and 9 grade, quarter 1 (8 lessons each), native ClassFlow slides, Kazakh only.
// Design work has no single right answer, so a practice slide has NO auto-check: the teacher marks the "Бағалау критерийі" slide by hand. Run: node scripts/gen-gd.mjs [partsDir]
import { writeFileSync, mkdirSync } from 'node:fs';
import assert from 'node:assert/strict';

// ---------- builders ----------
const title = (t, sub) => ({ type: 'title', pageType: 'slide', templateId: 'title', title: t, subtitle: sub });
const info = (kind, t, bullets, o = {}) => ({ type: 'content', pageType: 'slide', templateId: 'explanation', kind, title: t, bullets, ...(o.code ? { code: o.code, lang: 'text' } : {}), ...(o.notes ? { notes: o.notes } : {}) });
const walk = (t, task, steps, result, notes) => ({
  type: 'solution', pageType: 'slide', templateId: 'worked-example', kind: 'exampletask', title: t,
  sections: [{ h: 'Шарты', text: task }, { h: 'Қадамдар', bullets: steps }, { h: 'Нәтиже', text: result, hide: true }], ...(notes ? { notes } : {}),
});
const prac = (t, steps, notes) => ({ type: 'content', pageType: 'slide', templateId: 'practice', kind: 'practice', title: t, bullets: steps.map((s, i) => `${i + 1}. ${s}`), ...(notes ? { notes } : {}) });
const crit = (items, notes) => ({ type: 'content', pageType: 'slide', templateId: 'explanation', kind: 'explain', title: 'Бағалау критерийі', bullets: [...items.map((s, i) => `${i + 1} · ${s}`), `Әр критерий: орындалды — 1, орындалмады — 0. Барлығы ${items.length} ұпай.`], ...(notes ? { notes } : {}) });
const critP = (items, notes) => ({ type: 'content', pageType: 'slide', templateId: 'explanation', kind: 'explain', title: 'Бағалау критерийі', bullets: items, ...(notes ? { notes } : {}) });
const quiz = (t, prompt, options, answer, why) => ({ type: 'quiz', pageType: 'interactive', templateId: 'single-choice', kind: 'check', title: t, prompt, options, answer, explanation: why, points: 1 });
const Q = (n, prompt, options, answer, why) => quiz(`Өзіңді тексер · ${n}`, prompt, options, answer, why);
const tbl = rows => { const w = rows[0].map((_, c) => Math.max(...rows.map(r => String(r[c]).length))); return rows.map(r => r.map((x, c) => String(x).padEnd(w[c])).join(' | ')).join('\n'); };
const DEF = 'Тапсырма Figma-да орындалады. Мұғалімнің белгілеуі: орындалды — 1, орындалмады — 0.';
const PROJ = [ // 4 project criteria, 0-5 each (plan: "Бағалау критерийлері")
  'Идея және мақсат: 5 — жұмыс кім үшін және не үшін екені айқын, пайдалы · 3 — айтылған, бірақ жалпы · 1 — түсініксіз',
  'Дизайн сапасы: 5 — түс, қаріп, композиция таза, мәтін оқылады · 3 — кей жерлері тартымсыз · 1 — шатасқан',
  'Техника: 5 — қабаттар аталған, құралдар дұрыс қолданылған · 3 — бір бөлігі ретсіз · 1 — көбі ретсіз',
  'Қорғау және кері байланыс: 5 — жұмысын түсіндірді, кеңес бойынша өзгерткенін көрсетті · 3 — түсіндірді, өзгертпеді · 1 — түсіндіре алмады',
];

